schema:
{
  "description": "Inserisci il contratto nello scadenzario: compila i campi e scegli il metodo per ciascuno.",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true
  },
  "fieldSchema": {
    "fields": {
      "TipoServizio": {
        "type": "string",
        "method": "classify",
        "description": "Art. 1: categoria del servizio.",
        "enum": [
          "assistenza",
          "manutenzione",
          "noleggio",
          "pulizia",
          "software"
        ]
      },
      "RinnovoAutomatico": {
        "type": "string",
        "method": "classify",
        "description": "Art. 4: \"cessa senza disdetta\".",
        "enum": [
          "sì",
          "no"
        ]
      },
      "PreavvisoGiorni": {
        "type": "integer",
        "method": "extract",
        "description": "Giorni di preavviso per il recesso."
      },
      "DataInizio": {
        "type": "date",
        "method": "extract",
        "description": "Data di decorrenza."
      },
      "DurataMesi": {
        "type": "number",
        "method": "extract",
        "description": "Art. 2."
      }
    }
  }
}
